import { motion } from 'framer-motion'
import { Gift, Shuffle, Mic, RotateCcw } from 'lucide-react'
import { hapticMedium } from '@/utils/haptics'

interface BentoGridShowcaseProps {
  spinsLeft: number
  onOpenWheel: () => void
  onOpenRandomizer: () => void
  onOpenVoice: () => void
  onOpenQuickOrder: () => void
}

export function BentoGridShowcase({
  spinsLeft, onOpenWheel, onOpenRandomizer, onOpenVoice, onOpenQuickOrder
}: BentoGridShowcaseProps) {
  const quickActions = [
    {
      id: 'wheel',
      title: 'หมุนวงล้อ',
      subtitle: spinsLeft > 0 ? `${spinsLeft} สิทธิ์` : 'ลุ้นกินฟรี',
      badge: spinsLeft > 0 ? 'FREE' : undefined,
      icon: Gift,
      gradient: 'linear-gradient(135deg, #FF5500, #E03E00)',
      iconColor: '#FFFFFF',
      onClick: onOpenWheel,
    },
    {
      id: 'random',
      title: 'สุ่มเมนู',
      subtitle: 'คิดไม่ออก',
      icon: Shuffle,
      gradient: 'linear-gradient(135deg, #8B5CF6, #6D28D9)',
      iconColor: '#FFFFFF',
      onClick: onOpenRandomizer,
    },
    {
      id: 'voice',
      title: 'สั่งด้วยเสียง',
      subtitle: 'AI รับสั่ง',
      icon: Mic,
      gradient: 'linear-gradient(135deg, #0284C7, #0369A1)',
      iconColor: '#FFFFFF',
      onClick: onOpenVoice,
    },
    {
      id: 'reorder',
      title: 'สั่งซ้ำด่วน',
      subtitle: 'เมนูล่าสุด',
      icon: RotateCcw,
      gradient: 'linear-gradient(135deg, #10B981, #059669)',
      iconColor: '#FFFFFF',
      onClick: onOpenQuickOrder,
    },
  ]

  return (
    <div className="grid grid-cols-4 gap-2.5">
      {quickActions.map((action) => {
        const Icon = action.icon
        return (
          <motion.button
            key={action.id}
            type="button"
            whileHover={{ y: -3, scale: 1.02 }}
            whileTap={{ scale: 0.94 }}
            onClick={() => {
              hapticMedium()
              action.onClick()
            }}
            className="flex flex-col items-center p-2.5 rounded-[22px] border text-center transition-all relative overflow-hidden group cursor-pointer"
            style={{
              background: '#FFFFFF',
              borderColor: 'var(--border-subtle)',
              boxShadow: '0 2px 8px rgba(15, 23, 42, 0.04)',
            }}
          >
            {/* Icon Squircle */}
            <div
              className="w-11 h-11 rounded-[16px] flex items-center justify-center mb-1.5 shadow-sm transition-transform group-hover:scale-105"
              style={{ background: action.gradient }}
            >
              <Icon className="w-5 h-5 text-white" />
            </div>

            {/* Title */}
            <span className="font-black text-[11px] leading-tight text-slate-900 truncate w-full">
              {action.title}
            </span>

            {/* Subtitle / Badge */}
            <span className="text-[9px] font-bold text-slate-500 mt-0.5 truncate w-full">
              {action.subtitle}
            </span>

            {action.badge && (
              <span className="absolute top-1.5 right-1.5 text-[8px] font-black px-1.5 py-0.2 rounded-full bg-red-500 text-white animate-pulse">
                {action.badge}
              </span>
            )}
          </motion.button>
        )
      })}
    </div>
  )
}
