import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { useMenuItems } from '@/features/menu/hooks/useMenu'
import { searchEngine } from '@/features/ai/hooks/useSmartSearch'
import { useMenuStore, useAuthStore, useCartStore } from '@/store'
import { Container } from '@/components/layout/Container'
import { MenuGridSkeleton } from '@/components/ui/Skeleton'
import { trackPageView } from '@/lib/analytics'
import { useSEO } from '@/hooks/useSEO'
import { hapticHeavy } from '@/utils/haptics'
import { Flame, Sparkles } from 'lucide-react'

// Feature Components
import { HeroSlider } from '@/features/menu/components/HeroSlider'
import { CategoryTabs } from '@/features/menu/components/CategoryTabs'
import { MenuGrid } from '@/features/menu/components/MenuGrid'
import { SearchBar } from '@/features/menu/components/SearchBar'
import { FloatingCart } from '@/features/cart/components/FloatingCart'
import { MenuItemModal } from '@/features/menu/components/MenuItemModal'
import { ShopClosedBanner } from '@/features/config/components/ShopClosedBanner'
import { BentoGridShowcase } from '@/components/ui/BentoGridShowcase'
import { useIsShopOpen, useNextOpeningTime } from '@/features/config/hooks/useShopConfig'

// Interactive Feature Modals
import {
  WheelOfFortune,
  FoodRandomizer,
  VoiceOrder,
  QuickOrderModal,
  useWheelOfFortune
} from '@/features/games'
import type { MenuItem } from '@/types'

export default function HomePage() {
  const { data: menuItems, isLoading } = useMenuItems()
  const { activeCategory, searchQuery } = useMenuStore()
  const { user, isGuest } = useAuthStore()
  const { addItem } = useCartStore()
  const { spinsLeft } = useWheelOfFortune()
  const { data: isOpen } = useIsShopOpen()
  const { data: nextOpening } = useNextOpeningTime()

  const [showWheel, setShowWheel] = useState(false)
  const [showRandomizer, setShowRandomizer] = useState(false)
  const [showVoice, setShowVoice] = useState(false)
  const [showQuickOrder, setShowQuickOrder] = useState(false)
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null)

  useEffect(() => {
    trackPageView('/', 'Home')
    window.scrollTo(0, 0)
  }, [])

  useSEO({
    title: 'กะเพรา 52 — สั่งด่วน รสจัดจ้าน',
    description: 'กะเพรา 52 - เมนูกะเพราและอาหารตามสั่งรสเด็ด สั่งง่าย ส่งไว'
  })

  const favorites = useMenuStore(s => s.favorites)
  const filteredItems = menuItems
    ? (searchQuery
        ? searchEngine.search(menuItems, searchQuery).map(r => r.item)
        : menuItems.filter(item => {
            if (activeCategory === 'favorites') return favorites.includes(item.id)
            return item.category === activeCategory
          }))
    : []

  const handleWheelWin = (code: string, value: number) => useCartStore.getState().applyCoupon(code, value)
  const handleRandomizerSelect = (item: MenuItem) => setSelectedItem(item)

  const handleVoiceSelect = (item: MenuItem, options: { egg?: string; spicy?: string }) => {
    const selectedOptions = []
    if (options.egg) selectedOptions.push({ optionId: `egg-${options.egg}`, name: options.egg, price: options.egg === 'ไข่ดาว' ? 10 : 15 })
    if (options.spicy) selectedOptions.push({ optionId: `spicy-${options.spicy}`, name: `ความเผ็ด: ${options.spicy}`, price: 0 })
    addItem(item, 1, selectedOptions)
  }

  const handleQuickReorder = (order: { items: { name: string; quantity: number; price: number; menuItemId?: number }[] }) => {
    order.items.forEach(orderItem => {
      const menuItem = menuItems?.find(m => (orderItem.menuItemId && m.id === orderItem.menuItemId) || m.name === orderItem.name)
      if (menuItem) addItem(menuItem, orderItem.quantity, [])
    })
  }

  return (
    <div className="min-h-screen pb-36 relative" style={{ background: 'var(--bg-base)' }}>

      {/* === TOP APP BAR (Sleek 2026 Minimalist Header) === */}
      <header className="sticky top-0 z-[60] safe-area-pt">
        <div
          className="absolute inset-0"
          style={{
            background: 'rgba(255, 255, 255, 0.94)',
            backdropFilter: 'blur(30px) saturate(180%)',
            WebkitBackdropFilter: 'blur(30px) saturate(180%)',
            borderBottom: '1px solid rgba(15, 23, 42, 0.06)',
            boxShadow: '0 2px 12px rgba(15, 23, 42, 0.03)'
          }}
        />
        <Container size="full" className="py-2.5 px-4 relative z-10">
          <div className="flex items-center justify-between">

            {/* Brand Logo & Shop Status */}
            <div className="flex items-center gap-2.5">
              <div
                className="w-9 h-9 rounded-[12px] flex items-center justify-center font-black text-white text-base shadow-sm"
                style={{
                  background: 'linear-gradient(135deg, #FF5500, #E03E00)',
                  boxShadow: '0 4px 12px rgba(255, 85, 0, 0.35)',
                }}
              >
                K
              </div>
              <div>
                <div className="flex items-center gap-1">
                  <span className="font-black text-base tracking-tight text-slate-900">KAPRAO</span>
                  <span className="font-black text-base text-orange-600">52</span>
                  <Flame className="w-3.5 h-3.5 text-orange-500 fill-orange-500" />
                </div>
                {/* Dynamic Status Pill */}
                <div className="flex items-center gap-1.5 mt-0.5">
                  <span className="relative flex h-2 w-2">
                    <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${isOpen !== false ? 'bg-emerald-400' : 'bg-amber-400'}`} />
                    <span className={`relative inline-flex rounded-full h-2 w-2 ${isOpen !== false ? 'bg-emerald-500' : 'bg-amber-500'}`} />
                  </span>
                  <span className="text-[10px] font-black text-slate-500">
                    {isOpen !== false ? 'พร้อมรับออเดอร์' : `ปิด (เปิด ${nextOpening || '08:00'})`}
                  </span>
                </div>
              </div>
            </div>

            {/* Right Header Actions */}
            <div className="flex items-center gap-2">
              <SearchBar />

              {/* Guest LINE Login Button */}
              {isGuest && (
                <motion.button
                  type="button"
                  whileTap={{ scale: 0.92 }}
                  onClick={async () => {
                    hapticHeavy()
                    try {
                      const { loginWithLine } = await import('@/lib/auth')
                      await loginWithLine()
                    } catch (e) { console.error(e) }
                  }}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-white font-black text-xs shadow-sm cursor-pointer"
                  style={{
                    background: '#00C300',
                    boxShadow: '0 3px 10px rgba(0, 195, 0, 0.35)',
                  }}
                >
                  <span>LINE Login</span>
                </motion.button>
              )}

              {/* Member Points Chip */}
              {!isGuest && user && (
                <div
                  className="flex items-center gap-1 px-3 py-1.5 rounded-full border text-xs font-black text-amber-700 bg-amber-50"
                  style={{ borderColor: 'rgba(245, 158, 11, 0.3)' }}
                >
                  <Sparkles className="w-3.5 h-3.5 text-amber-500" />
                  <span className="num-display">{user.points || 0} pts</span>
                </div>
              )}
            </div>

          </div>
        </Container>
      </header>

      {/* === MAIN FEED === */}
      <Container size="full" className="px-4 pt-3 space-y-4 relative z-10">

        {/* 1. Shop Closed Banner (If closed) */}
        {isOpen === false && (
          <ShopClosedBanner />
        )}

        {/* 2. Hero Slider (Clean compact aspect ratio) */}
        <HeroSlider />

        {/* 3. Interactive Quick Actions Bar (1-Row, Modern & Sleek) */}
        <BentoGridShowcase
          spinsLeft={spinsLeft}
          onOpenWheel={() => setShowWheel(true)}
          onOpenRandomizer={() => setShowRandomizer(true)}
          onOpenVoice={() => setShowVoice(true)}
          onOpenQuickOrder={() => setShowQuickOrder(true)}
        />

        {/* 4. Menu Section */}
        <div className="pt-2 space-y-3">
          <div className="flex items-center justify-between px-1">
            <div className="flex items-center gap-2">
              <span className="w-1.5 h-4 rounded-full bg-orange-500" />
              <h2 className="font-black text-base text-slate-900 tracking-tight">
                {searchQuery ? `ผลการค้นหา "${searchQuery}"` : 'รายการอาหาร'}
              </h2>
            </div>
            <span
              className="text-[11px] font-black px-2.5 py-0.5 rounded-full text-orange-600 bg-orange-50 border border-orange-200"
            >
              {filteredItems?.length || 0} เมนู
            </span>
          </div>

          {/* Sticky Category Pills */}
          <CategoryTabs />

          {/* Food Grid */}
          <div className="min-h-[350px] pt-1">
            {isLoading ? (
              <MenuGridSkeleton count={6} />
            ) : (
              <MenuGrid items={filteredItems || []} />
            )}
          </div>
        </div>

      </Container>

      {/* Floating Cart Indicator */}
      <FloatingCart />

      {/* Feature Modals */}
      <WheelOfFortune isOpen={showWheel} onClose={() => setShowWheel(false)} onWin={handleWheelWin} />
      <FoodRandomizer isOpen={showRandomizer} onClose={() => setShowRandomizer(false)} onSelect={handleRandomizerSelect} />
      <VoiceOrder isOpen={showVoice} onClose={() => setShowVoice(false)} onSelect={handleVoiceSelect} />
      <QuickOrderModal isOpen={showQuickOrder} onClose={() => setShowQuickOrder(false)} onReorder={handleQuickReorder} />

      {selectedItem && (
        <MenuItemModal
          item={selectedItem}
          isOpen={!!selectedItem}
          onClose={() => setSelectedItem(null)}
        />
      )}
    </div>
  )
}
